<?php
declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';if(is_file(__DIR__.'/../app/access_control_v1300.php'))require_once __DIR__.'/../app/access_control_v1300.php';require_once __DIR__.'/../app/lms_v1360.php';sk1360_require_login();$s=sk1360_student(sk1360_uid(),true);$pdo=sk1360_db();$q=$pdo->prepare("SELECT e.*,c.title,c.slug,c.summary,c.category,c.level,c.code FROM lms_enrollments_v1360 e JOIN lms_courses_v1360 c ON c.id=e.course_id AND c.tenant_id=e.tenant_id WHERE e.tenant_id=? AND e.student_id=? ORDER BY e.updated_at DESC");$q->execute([sk1360_tid(),(int)$s['id']]);$en=$q->fetchAll(PDO::FETCH_ASSOC)?:[];sk1360_lms_shell('My Learning','student');?><section class="portal-hero"><div><span class="eyebrow">STUDENT PORTAL</span><h1>My Learning</h1><p><?=sk1360_h($s['student_no'])?> · Track courses, lessons, assessments and certificates.</p></div><a class="btn" href="/education-network.php">Browse Courses</a></section><div class="portal-grid"><?php foreach($en as $e):?><article class="course-card"><span class="course-state"><?=sk1360_h($e['status'])?></span><h2><?=sk1360_h($e['title'])?></h2><p><?=sk1360_h($e['summary'])?></p><div class="progress"><i style="width:<?=max(0,min(100,(int)$e['progress_percent']))?>%"></i></div><small><?=$e['progress_percent']?>% complete · <?=sk1360_h($e['category'])?></small><a class="btn" href="/student/lms-course.php?id=<?=$e['course_id']?>">Continue Learning</a></article><?php endforeach;?></div><?php sk1360_lms_end();
